namespace Ncw.Protocol.Tests;

/// <summary>
/// 云端 Agent 客户端可见类型的冻结向量(协议 v1,M6 云端批次生成)。旧向量不动:这一批只新增方法 / 载荷类型和 <c>ProjectsAddParams</c> 的带默认值的末尾字段
/// (<c>CloneUrl</c> / <c>CloneBranch</c>:旧载荷没有这两个键,必须照常解码,见 <see cref="ProjectsAddParamsBeforeClone"/>)。
/// 测试失败说明某个 DTO 的键名 / 形状变了,那必须升协议版本或加能力开关,不能直接改向量。
/// </summary>
internal static class GoldenV1Cloud
{
    /// <summary>加 CloneUrl / CloneBranch 之前的 projects.add 载荷(旧控制端发来的,含 EnvironmentId):必须仍能解码。</summary>
    public const string ProjectsAddParamsBeforeClone =
        "83a450617468a82f7372762f617070a44e616d65a3617070ad456e7669726f6e6d656e744964a437633166";

    public const string Status =
        "";
    public const string StatusUnlimited =
        "";
    public const string ClearInterruptedParams =
        "81a652756e49647392a572756e2d31a572756e2d32";
    public const string CredentialSetParams =
        "83a4486f7374aa6769746875622e636f6da5546f6b656eab6768705f6578616d706c65a8557365726e616d65ae782d6163636573732d746f6b656e";
    public const string CredentialSetParamsNoUser =
        "83a4486f7374b46769742e6578616d706c652e636f6d3a38343433a5546f6b656ea3746f6ba8557365726e616d65c0";
    public const string CredentialRemoveParams =
        "81a4486f7374aa6769746875622e636f6d";
    public const string CredentialsResult =
        "81ab43726564656e7469616c739182a4486f7374aa6769746875622e636f6da8557365726e616d65ae782d6163636573732d746f6b656e";
    public const string ProjectsAddClone =
        "85a450617468a8776f726b2f617070a44e616d65a3617070ad456e7669726f6e6d656e744964c0a8436c6f6e6555726cbe68747470733a2f2f6769746875622e636f6d2f6f72672f6170702e676974ab436c6f6e654272616e6368a46d61696e";
    public const string ProjectsAddCloneDefaultBranch =
        "85a450617468a8776f726b2f617070a44e616d65c0ad456e7669726f6e6d656e744964c0a8436c6f6e6555726cbe68747470733a2f2f6769746875622e636f6d2f6f72672f6170702e676974ab436c6f6e654272616e6368c0";

    public static string Of(string name) => name switch
    {
        "cloud.status" => Status,
        "cloud.status.unlimited" => StatusUnlimited,
        "cloud.clearInterrupted.params" => ClearInterruptedParams,
        "git.credentials.set.params" => CredentialSetParams,
        "git.credentials.set.paramsNoUser" => CredentialSetParamsNoUser,
        "git.credentials.remove.params" => CredentialRemoveParams,
        "git.credentials.result" => CredentialsResult,
        "projects.add.clone" => ProjectsAddClone,
        "projects.add.cloneDefaultBranch" => ProjectsAddCloneDefaultBranch,
        _ => throw new ArgumentOutOfRangeException(nameof(name), name, null),
    };
}
